#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;
    // Assumes A.size() == N*N.

    // Doolittle LU factorization in-place:
    // - U stored on and above diagonal
    // - L stored below diagonal with implicit unit diagonal
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute multipliers for column k (L entries below diagonal).
        #pragma omp parallel for default(none) shared(A, N, k, pivot)
        for (size_t i = k + 1; i < N; ++i) {
            A[i * N + k] /= pivot;
        }

        // Update trailing submatrix:
        // A[i,j] -= A[i,k] * A[k,j], for i,j > k
        #pragma omp parallel for collapse(2) default(none) shared(A, N, k)
        for (size_t i = k + 1; i < N; ++i) {
            for (size_t j = k + 1; j < N; ++j) {
                A[i * N + j] -= A[i * N + k] * A[k * N + j];
            }
        }
    }
}
